'use client'

import * as React from 'react'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled ProgressBar, and `tsc --noEmit` passes on it,
// so the gate cannot catch it.
import './progress-bar.css'
import { TickGlyph } from './glyphs'

/**
 * ProgressBar: how far through something a player is.
 *
 * BDS-022 makes this the base for `milestones` and `quest`, so its shape is
 * load-bearing for two components that do not exist yet. Everything those two
 * need is here and nothing else is: a bounded value, the four states, and one
 * custom property carrying the fraction for the fill geometry.
 *
 * There is no `data-gs-progress` and no `data-gs-fill`. How far through
 * something is, is `data-gs-value` over `data-gs-max`, which is how every other
 * bounded value in the library is expressed, and inventing a third name for it
 * would give `lives`, `milestones` and this component three vocabularies for
 * one idea. CSS cannot divide one attribute by another, so the fraction the
 * fill needs is a custom property, `--gs-progress`, and a custom property is
 * not an attribute: nothing selects on it, no test reads it as state, and it
 * carries no meaning the attributes do not already carry.
 *
 * It performs nothing. The host owns the number, decides when the thing is
 * finished, and says so.
 */

export interface ProgressBarProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, 'children'> {
  /**
   * How far along. Absent only when `indeterminate`. Zero is a real state and
   * renders as one, so this is never dropped for being falsy.
   */
  value?: number
  /** The ceiling the value counts toward. */
  max?: number
  /** The floor the value counts from. Omitted from the DOM when it is zero. */
  min?: number
  /** Working, with no known fraction. The value is ignored and not announced. */
  indeterminate?: boolean
  /** Finished. The host decides; the component never infers it from the number. */
  complete?: boolean
  /** The word a player reads as this bar's name. */
  label?: string
  /** Render the value as something other than the bare number, e.g. `40%`. */
  format?: (value: number) => string
  /** Show the label and the figure above the track. */
  showLabel?: boolean
  /**
   * Show the figure inside the track, centred over the fill, as specimen 3c's
   * XP bar does ("1,360 / 2,000 XP"). The track grows to hold the text.
   */
  inlineValue?: boolean
  /**
   * The bookends: what the track runs from and what it runs to. Specimen 3c
   * draws a level number at each end of the XP bar, the reached one on a
   * raised disc and the next one dashed and muted until the bar fills. Each is
   * a milestone on the track, so each renders as one: `from` reached,
   * `to` locked until `complete`.
   */
  from?: React.ReactNode
  to?: React.ReactNode
}

/**
 * The words that go with the states, fixed by the attribute contract so that
 * `progress-bar`, `level-ring`, `milestones` and `quest` cannot ship four
 * vocabularies for the same two states.
 */
const STATE_WORD = {
  indeterminate: 'in progress',
  complete: 'complete',
} as const

/** The tick, because a state that is only a colour is not a state. */
const COMPLETE_GLYPH = <TickGlyph />

/**
 * The fraction the fill geometry needs, clamped to the track.
 *
 * A host reporting 120 of 100 gets a full bar rather than a fill that overruns
 * its track, and `data-gs-value` still carries the 120, because the attribute
 * is the truth and the geometry is a rendering of it.
 */
export function progressFraction(value: number, min: number, max: number): number {
  const span = max - min
  if (!Number.isFinite(span) || span <= 0) return 0
  return Math.min(1, Math.max(0, (value - min) / span))
}

export function ProgressBar({
  value,
  max = 100,
  min = 0,
  indeterminate = false,
  complete = false,
  label = 'progress',
  format,
  showLabel = false,
  inlineValue = false,
  from,
  to,
  className,
  style,
  ...rest
}: ProgressBarProps) {
  // Indeterminate means there is no fraction, so there is no value to read and
  // none to announce. Anything a host passed alongside it is ignored rather
  // than rendered, because a bar that is both 40% and unknowable is neither.
  const determinate = !indeterminate && value !== undefined
  const fraction = determinate ? progressFraction(value, min, max) : 0
  const rendered = determinate ? (format ? format(value) : `${value}`) : undefined

  // The name carries the state, because a screen reader user gets no fill, no
  // colour and no motion. Order: what it is, then where it is, then what is
  // true about it.
  const words = [label]
  if (determinate) words.push(`${rendered} of ${max}`)
  else words.push(STATE_WORD.indeterminate)
  // The bookends are part of the name when they are words or numbers, because
  // "level 12 to 13" is what the two discs say and a screen reader gets no
  // disc. A node the host built is left out rather than read as "[object]".
  const plain = (node: React.ReactNode) => typeof node === 'string' || typeof node === 'number'
  if (plain(from) && plain(to)) words.push(`${from} to ${to}`)
  if (complete) words.push(STATE_WORD.complete)

  // A bookend is a milestone at the end of the track: the one the player has
  // come from is reached, and the one they are going to is locked until the
  // bar fills. The number inside stands where a locked milestone's padlock
  // would: it is the level a player is waiting for, and it says so.
  const bookend = (node: React.ReactNode, reached: boolean) => (
    <span
      className="gs-progress-bar__bookend"
      data-gs-scope="progress-bar" data-gs-part="milestone"
      data-gs-complete={reached ? 'true' : undefined}
      data-gs-locked={reached ? undefined : 'true'}
      aria-hidden="true"
    >
      {node}
    </span>
  )

  return (
    <div
      {...rest}
      className={['gs-progress-bar', className].filter(Boolean).join(' ')}
      style={{ ...style, '--gs-progress': fraction } as React.CSSProperties}
      data-gs-component="progress-bar"
      data-gs-value={determinate ? value : undefined}
      data-gs-max={determinate ? max : undefined}
      data-gs-min={determinate && min !== 0 ? min : undefined}
      data-gs-indeterminate={indeterminate ? 'true' : undefined}
      data-gs-complete={complete ? 'true' : undefined}
      role="progressbar"
      // No aria-valuenow at all when indeterminate: that absence is what tells
      // a screen reader the bar is working rather than sitting at zero.
      aria-valuenow={determinate ? value : undefined}
      aria-valuemin={min}
      aria-valuemax={max}
      aria-label={words.join(', ')}
    >
      {showLabel ? (
        // aria-hidden throughout: the root's label above is the accessible
        // name, and announcing the pieces again would read the figure twice.
        <div className="gs-progress-bar__header" aria-hidden="true">
          <span className="gs-progress-bar__label" data-gs-scope="progress-bar" data-gs-part="label">
            {label}
          </span>
          {determinate ? (
            <span className="gs-progress-bar__value gs-display-type" data-gs-scope="progress-bar" data-gs-part="value">
              {rendered}
            </span>
          ) : null}
        </div>
      ) : null}

      {from !== undefined ? bookend(from, true) : null}

      <div
        className={['gs-progress-bar__track', inlineValue ? 'gs-progress-bar__track--readout' : null]
          .filter(Boolean)
          .join(' ')}
        data-gs-scope="progress-bar" data-gs-part="track"
        aria-hidden="true"
      >
        {/* The fill moves, so it is motion and stops dead under reduced motion.
            That is why completion must also change something that is not
            motion: the track's edge and the glyph below are emphasis and
            survive, so a reduced-motion player still sees it land. */}
        <div
          className="gs-progress-bar__fill"
          data-gs-scope="progress-bar" data-gs-part="fill"
          data-gs-motion="fill"
          data-gs-animates="motion"
        />
        {inlineValue && determinate ? (
          <span className="gs-progress-bar__readout" data-gs-scope="progress-bar" data-gs-part="value">
            {rendered}
          </span>
        ) : null}
      </div>

      {to !== undefined ? bookend(to, complete) : null}

      {complete ? (
        // The drawing says "on full: motion.celebrate" (3c). It is not wired
        // here, deliberately: this glyph is the emphasis half of completion,
        // the change a reduced-motion player gets, and the contract keeps an
        // element to one of motion or emphasis. The celebration belongs to
        // whatever the host shows for the full bar, a feedback or a reward,
        // both of which play it.
        <span
          className="gs-progress-bar__glyph"
          data-gs-scope="progress-bar" data-gs-part="glyph"
          data-gs-animates="emphasis"
          aria-hidden="true"
        >
          {COMPLETE_GLYPH}
        </span>
      ) : null}
    </div>
  )
}

/* Progress bar. Every value comes from a token; nothing here is a literal
   colour, size, duration or typeface.

   Specimen 3c draws this bar twice and design/twins/3c.json measures ours
   against both: the XP bar, a 26px pill with the figure inside it and a level
   disc at each end, and the milestone track underneath, the same pill at 14px
   with nothing in it. One component, one track, one fill; the readout is what
   makes the track taller. */

.gs-progress-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  /* The drawing's row gap between disc and track is 10px, space.gap. */
  gap: var(--gs-space-1) var(--gs-space-gap);
  width: 100%;

  /* The fill's fraction, set by the component. Declared here too so the
     stylesheet is legible on its own and a track with no inline style still
     renders an empty bar rather than an invalid width. */
  --gs-progress: 0;
}

.gs-progress-bar__header {
  flex-basis: 100%;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--gs-space-2);
}

.gs-progress-bar__label {
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
  letter-spacing: var(--gs-type-label-letter-spacing);
  text-transform: uppercase;
  color: var(--gs-color-ink-secondary);
}

/* Tabular numerals, or the figure jitters sideways as the bar fills. */
.gs-progress-bar__value {
  font-family: var(--gs-type-stat-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-stat-font-weight);
  font-variant-numeric: var(--gs-type-score-font-variant-numeric);
  color: var(--gs-color-ink);
}

/* The track is a hole punched in the surface: filled with colour.edge, the
   dark, with no stroke of its own. The drawing draws it 14px; icon.utility is
   16 and the twins file carries the 2px. */
.gs-progress-bar__track {
  position: relative;
  flex: 1 1 0;
  min-width: 0;
  overflow: hidden;
  box-sizing: border-box;
  height: var(--gs-size-icon-utility);
  border-radius: var(--gs-radius-full);
  background: var(--gs-color-edge);
  box-shadow: var(--gs-depth-flat);
}

/* With the figure inside, the track grows to hold it: the drawing draws 26px
   with 4px of padding round an 18px fill. icon.control and space.1 are the
   nearest tokens, 24 and 4, and the twins file carries the 2px. */
.gs-progress-bar__track--readout {
  height: var(--gs-size-icon-control);
  padding: var(--gs-space-1);
}

/* The fill is positive, the green, whether or not the bar is done: the
   drawing fills a 68% XP bar and a 55% milestone track in it, and completion
   is said by the track's edge and the glyph rather than by a change of hue.

   The lit top edge is depth.pressablePressed, the library's one inset
   highlight. The drawing's is 2px at .5 and the token is 3px at .45; a token
   for the bar's own highlight is requested in the twins file. */
.gs-progress-bar__fill {
  height: 100%;
  width: calc(var(--gs-progress) * 100%);
  border-radius: inherit;
  background: var(--gs-color-positive);
  box-shadow: var(--gs-depth-pressable-pressed);

  /* BDS-022: the fill runs over motion.fill on the drawing's curve,
     cubic-bezier(.2,.8,.3,1) (specimen 4a, "fill 600ms"). Only the width is
     timed here. motion.css applies the same transition to anything carrying
     data-gs-motion="fill"; it is restated here so the stylesheet reads on its
     own. */
  transition: width var(--gs-motion-fill) var(--gs-motion-ease-fill);
}

/* The figure inside the track, centred over the fill. The drawing sets it at
   11px, under the 12px floor; type.figure is the display face at its smallest
   token size. The drawing's 1px hard shadow under it has no token: the display
   shadow is 3px and doubles a 14px glyph, so none until one exists. */
.gs-progress-bar__readout {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--gs-type-figure-font-family);
  font-size: var(--gs-type-figure-font-size);
  font-weight: var(--gs-type-figure-font-weight);
  font-variant-numeric: var(--gs-type-score-font-variant-numeric);
  line-height: 1;
  color: var(--gs-color-ink);
}

/* A level disc at either end of the track: control.medium, ringed at the
   control stroke in edge, the figure face inside. The one behind the player
   sits on the raised surface; the one ahead is the dark with a dashed, muted
   ring, which is what the drawing does to every locked thing. */
.gs-progress-bar__bookend {
  flex: none;
  display: flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
  width: var(--gs-size-control-medium);
  height: var(--gs-size-control-medium);
  border-radius: var(--gs-radius-full);
  border: var(--gs-stroke-ui, var(--gs-stroke-hairline)) solid var(--gs-color-edge);
  background: var(--gs-color-surface-raised);
  font-family: var(--gs-type-figure-font-family);
  font-size: var(--gs-type-figure-font-size);
  font-weight: var(--gs-type-figure-font-weight);
  font-variant-numeric: var(--gs-type-score-font-variant-numeric);
  line-height: 1;
  color: var(--gs-color-ink);
}

.gs-progress-bar__bookend[data-gs-locked='true'] {
  background: var(--gs-color-edge);
  border-style: dashed;
  border-color: var(--gs-color-muted);
  color: var(--gs-color-muted);
}

/* Zero is a state, not an absence. The bar keeps a visible nub so the player
   sees a bar at the start line rather than a component that failed to render,
   and the track's own inset shape says how far there is to go. */
.gs-progress-bar[data-gs-value='0'] .gs-progress-bar__fill {
  min-width: var(--gs-stroke-selected);
}

/* -- indeterminate -------------------------------------------------------- */
/* A band that sweeps the track. The sweep is motion and stops under reduced
   motion, so the band is also given a width and a colour of its own: a player
   who sees no movement still sees a bar that is plainly not at a position,
   and the accessible name says "in progress" either way. */
.gs-progress-bar[data-gs-indeterminate='true'] .gs-progress-bar__fill {
  width: 40%;
  background: var(--gs-color-muted);
  box-shadow: none;
  animation: gs-progress-sweep var(--gs-motion-reveal) ease-in-out infinite alternate;
}

@keyframes gs-progress-sweep {
  from { transform: translateX(-100%); }
  to   { transform: translateX(250%); }
}

/* -- complete ------------------------------------------------------------- */
/* Completion changes two things that are not motion: the track gains a
   stroke in positive, and a glyph appears beside it. Both survive reduced
   motion, so a player for whom the fill never travels still sees it land. */
.gs-progress-bar[data-gs-complete='true'] .gs-progress-bar__track {
  border: var(--gs-stroke-ui, var(--gs-stroke-hairline)) solid var(--gs-color-positive-solid);
  transition: border-color var(--gs-motion-emphasis) ease-out;
}

.gs-progress-bar__glyph {
  flex: none;
  font-family: var(--gs-type-stat-font-family);
  font-size: var(--gs-size-icon-utility);
  line-height: 1;
  color: var(--gs-color-positive-solid);
  /* Emphasis, not motion: this duration survives reduced motion on purpose. */
  transition: opacity var(--gs-motion-emphasis) ease-out;
}
